import{_ as t,o,c as a,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const c=JSON.parse('{"title":"Adoption Guide","description":"Component of the Agentic Development Framework documentation.","frontmatter":{"type":"Agentic Development Framework","title":"Adoption Guide","description":"Component of the Agentic Development Framework documentation.","tags":["framework","internal"],"isInternal":true},"headers":[],"relativePath":"framework/adoption-guide.md","filePath":"framework/adoption-guide.md"}'),i={name:"framework/adoption-guide.md"};function n(s,e,d,l,u,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h2 id="_6-adoption-guide" tabindex="-1">6. Adoption Guide <a class="header-anchor" href="#_6-adoption-guide" aria-label="Permalink to &quot;6. Adoption Guide&quot;">​</a></h2><h3 id="step-1-create-the-agent-rules-file-30-minutes" tabindex="-1">Step 1: Create the Agent Rules File (30 minutes) <a class="header-anchor" href="#step-1-create-the-agent-rules-file-30-minutes" aria-label="Permalink to &quot;Step 1: Create the Agent Rules File (30 minutes)&quot;">​</a></h3><p>Create <code>.idx/airules.md</code> (or your platform&#39;s equivalent) with:</p><ul><li>A persona definition for your tech stack</li><li>Your team&#39;s coding standards (line length, indentation, type safety)</li><li>A placeholder for context routing rules (fill in as you go)</li></ul><h3 id="step-2-extract-your-first-skill-1-hour" tabindex="-1">Step 2: Extract Your First Skill (1 hour) <a class="header-anchor" href="#step-2-extract-your-first-skill-1-hour" aria-label="Permalink to &quot;Step 2: Extract Your First Skill (1 hour)&quot;">​</a></h3><p>Identify the domain where your agent makes the most mistakes. Write a <code>SKILL.md</code> in <code>.agents/skills/&lt;domain&gt;/</code> with concrete ❌ WRONG / ✅ CORRECT examples. Reference it from the agent rules file.</p><h3 id="step-3-add-context-routing-1-hour" tabindex="-1">Step 3: Add Context Routing (1 hour) <a class="header-anchor" href="#step-3-add-context-routing-1-hour" aria-label="Permalink to &quot;Step 3: Add Context Routing (1 hour)&quot;">​</a></h3><p>In the agent rules file, define 2–3 trigger-based routing rules with exclusion zones. Start with the most token-expensive path (the one where the agent reads the most irrelevant files).</p><h3 id="step-4-enable-agentic-tdd-ongoing" tabindex="-1">Step 4: Enable Agentic TDD (ongoing) <a class="header-anchor" href="#step-4-enable-agentic-tdd-ongoing" aria-label="Permalink to &quot;Step 4: Enable Agentic TDD (ongoing)&quot;">​</a></h3><p>Add the four-step TDD cycle to the agent rules file. Start with one test framework (e.g., Playwright for E2E) and expand to unit tests later.</p><h3 id="step-5-add-self-updating-memory-2-hours" tabindex="-1">Step 5: Add Self-Updating Memory (2 hours) <a class="header-anchor" href="#step-5-add-self-updating-memory-2-hours" aria-label="Permalink to &quot;Step 5: Add Self-Updating Memory (2 hours)&quot;">​</a></h3><p>Create the <code>self-updating-memory/SKILL.md</code> with the harvesting algorithm. Create <code>docs/adr/index.md</code>. Start using <code>/learn</code> after complex debugging sessions.</p><h3 id="step-6-introduce-swarm-roles-when-team-is-ready" tabindex="-1">Step 6: Introduce Swarm Roles (when team is ready) <a class="header-anchor" href="#step-6-introduce-swarm-roles-when-team-is-ready" aria-label="Permalink to &quot;Step 6: Introduce Swarm Roles (when team is ready)&quot;">​</a></h3><p>Create the three role skill files. Start by using Architect + Builder for the next significant feature. Add the Reviewer role after the team has built confidence in the workflow.</p><h3 id="step-7-close-the-ci-cd-loop-when-infrastructure-supports-it" tabindex="-1">Step 7: Close the CI/CD Loop (when infrastructure supports it) <a class="header-anchor" href="#step-7-close-the-ci-cd-loop-when-infrastructure-supports-it" aria-label="Permalink to &quot;Step 7: Close the CI/CD Loop (when infrastructure supports it)&quot;">​</a></h3><p>Create <code>git-promotion-workflow/SKILL.md</code> with your branch strategy and deployment verification steps. Optionally, build a custom MCP server for production log querying.</p><hr>',17)])])}const m=t(i,[["render",n]]);export{c as __pageData,m as default};
